components.css:
.ds-btn { font-family: "Readex Pro Variable", sans-serif; font-size: 16px; min-height: 40px; padding: 8px 16px; border-radius: var(--r-control, 8px); display: inline-flex; align-items: center; justify-content: center; gap: 8px; white-space: nowrap; cursor: pointer; transition: background-color 140ms ease-out, border-color 140ms ease-out, color 140ms ease-out; }
.ds-btn:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: 2px; }
.ds-btn-primary { background: var(--action, #4f46c8); color: #fff; border: 1px solid var(--action, #4f46c8); font-weight: 600; }
.ds-btn-primary:hover { background: var(--action-ink, #3f37a8); border-color: var(--action-ink, #3f37a8); }
.ds-btn-primary:active { background: var(--scene, #1e1b52); border-color: var(--scene, #1e1b52); }
.ds-btn-primary:disabled { background: var(--line, #e1e3ee); border-color: var(--line, #e1e3ee); color: var(--soft, #666b85); cursor: not-allowed; }

