.ds-btn:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: 2px; }
.ds-btn-bordered { background: var(--surface, #fff); border: 1px solid var(--line-strong, #c7cadb); color: var(--ink, #14162b); font-weight: 500; }
.ds-btn-bordered:hover { background: var(--hover, #ecedf5); border-color: var(--soft, #666b85); }
.ds-btn-bordered:active { background: var(--action-tint, #ecebfb); }
.ds-btn-quiet { background: transparent; border: 1px solid transparent; color: var(--late, #b42318); font-weight: 500; margin-inline-start: 8px; }
.ds-btn-quiet:hover { background: var(--late-tint, #fdecea); border-color: var(--late-line, #f3c2bc); }

.ds-heading { font-family: "Readex Pro Variable", sans-serif; color: var(--ink, #14162b); position: relative; display: flex; align-items: flex-end; justify-content: space-between; flex-wrap: wrap; gap: 14px 20px; padding-bottom: 18px; border-bottom: 1px solid var(--line, #e1e3ee); }
.ds-heading::after { content: ''; position: absolute; inset-inline-start: 0; bottom: -2px; width: 72px; height: 3px; background: var(--mark, #4f46c8); }
.ds-heading h1 { margin: 0; font-size: 26px; font-weight: 600; line-height: 1.35; }
.ds-heading p { margin: 6px 0 0; color: var(--muted, #454a63); font-size: 14px; }
.ds-btn { font-family: "Readex Pro Variable", sans-serif; font-size: 16px; min-height: 40px; padding: 8px 16px; border-radius: var(--r-control, 8px); display: inline-flex; align-items: center; justify-content: center; gap: 8px; white-space: nowrap; cursor: pointer; transition: background-color 140ms ease-out, border-color 140ms ease-out, color 140ms ease-out; }
.ds-btn:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: 2px; }
.ds-btn-primary { background: var(--action, #4f46c8); color: #fff; border: 1px solid var(--action, #4f46c8); font-weight: 600; }
.ds-btn-primary:hover { background: var(--action-ink, #3f37a8); border-color: var(--action-ink, #3f37a8); }
.ds-btn-primary:active { background: var(--scene, #1e1b52); border-color: var(--scene, #1e1b52); }
.ds-btn-primary:disabled { background: var(--line, #e1e3ee); border-color: var(--line, #e1e3ee); color: var(--soft, #666b85); cursor: not-allowed; }

.ds-strip { font-family: "Readex Pro Variable", sans-serif; color: var(--ink, #14162b); display: grid; grid-template-columns: repeat(auto-fit, minmax(136px, 1fr)); gap: 0; background: var(--surface, #fff); border: 1px solid var(--line, #e1e3ee); border-radius: var(--radius, 12px); overflow: hidden; }
.ds-strip p { margin: 0; padding: 16px 18px; background: var(--surface, #fff); box-shadow: 0 0 0 1px var(--line, #e1e3ee); display: grid; align-content: start; gap: 4px; min-width: 0; }
.ds-strip span { color: var(--muted, #454a63); font-size: 13px; }
.ds-strip strong { font-size: 28px; font-weight: 600; line-height: 1.2; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; white-space: nowrap; }
.ds-strip small { color: var(--muted, #454a63); font-size: 12px; }
.ds-strip .ds-late { color: var(--late, #b42318); }

.ds-rail { font-family: "Readex Pro Variable", sans-serif; width: 256px; display: flex; flex-direction: column; gap: 2px; padding: 20px 14px 14px; background: var(--surface, #fff); border-inline-end: 1px solid var(--line, #e1e3ee); }
.ds-rail p { margin: 16px 12px 6px; color: var(--soft, #666b85); font-size: 12px; font-weight: 500; }
.ds-rail a { color: var(--muted, #454a63); text-decoration: none; font-size: 14px; padding: 8px 12px; border-radius: var(--r-control, 8px); min-height: 40px; display: flex; align-items: center; gap: 12px; transition: background-color 140ms ease-out, color 140ms ease-out; }
.ds-rail a:hover { background: var(--hover, #ecedf5); color: var(--ink, #14162b); }
.ds-rail a.ds-on { background: var(--mark-tint, #ecebfb); color: var(--mark-ink, #3f37a8); font-weight: 600; }
.ds-rail a:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: 2px; }
.ds-rail bdi { margin-inline-start: auto; min-width: 22px; height: 22px; padding: 0 7px; border-radius: 999px; background: var(--action, #4f46c8); color: #fff; font-size: 12px; font-weight: 600; display: inline-grid; place-items: center; font-variant-numeric: tabular-nums; }

.ds-tabs { font-family: "Readex Pro Variable", sans-serif; display: flex; gap: 4px; border-bottom: 1px solid var(--line, #e1e3ee); overflow-x: auto; scrollbar-width: none; }
.ds-tabs a { display: inline-flex; align-items: center; min-height: 44px; padding: 8px 14px; color: var(--muted, #454a63); text-decoration: none; border-bottom: 3px solid transparent; margin-bottom: -1px; white-space: nowrap; font-size: 15px; transition: color 140ms ease-out, background-color 140ms ease-out; }
.ds-tabs a:hover { color: var(--ink, #14162b); background: var(--hover, #ecedf5); }
.ds-tabs a.ds-active { color: var(--ink, #14162b); border-bottom-color: var(--mark, #4f46c8); font-weight: 600; }
.ds-tabs a:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: -2px; }

.ds-seg { display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 3px; background: var(--hover, #ecedf5); border-radius: var(--r-control, 8px); width: fit-content; }
.ds-seg button { font-family: "Readex Pro Variable", sans-serif; border: 0; border-radius: 6px; background: transparent; color: var(--muted, #454a63); min-height: 36px; padding: 6px 16px; font-size: 14px; cursor: pointer; transition: background-color 140ms ease-out, color 140ms ease-out; }
.ds-seg button:hover { color: var(--ink, #14162b); }
.ds-seg button.ds-on { background: var(--surface, #fff); color: var(--mark-ink, #3f37a8); font-weight: 600; box-shadow: 0 0 0 1px var(--line-strong, #c7cadb); }
.ds-seg button:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: 2px; }

.ds-filters { font-family: "Readex Pro Variable", sans-serif; display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px 14px; padding: 16px 18px; background: var(--surface, #fff); border: 1px solid var(--line, #e1e3ee); border-radius: var(--radius, 12px); }
.ds-filters label { display: flex; flex-direction: column; gap: 6px; color: var(--muted, #454a63); font-size: 13px; min-width: 0; }
.ds-filters input, .ds-filters select { font-family: inherit; font-size: 16px; color: var(--ink, #14162b); width: 100%; min-height: 40px; border: 1px solid var(--line-strong, #c7cadb); border-radius: var(--r-control, 8px); background: var(--surface, #fff); padding: 0 12px; caret-color: var(--action, #4f46c8); transition: border-color 140ms ease-out, box-shadow 140ms ease-out; }
.ds-filters input::placeholder { color: var(--soft, #666b85); opacity: 1; }
.ds-filters input:hover, .ds-filters select:hover { border-color: var(--soft, #666b85); }
.ds-filters input:focus-visible, .ds-filters select:focus-visible { border-color: var(--action, #4f46c8); outline: 0; box-shadow: 0 0 0 3px var(--action-tint, #ecebfb); }

.ds-sheet { font-family: "Readex Pro Variable", sans-serif; color: var(--ink, #14162b); background: var(--surface, #fff); border: 1px solid var(--line, #e1e3ee); border-radius: var(--radius, 12px); overflow-x: auto; }
.ds-sheet table { width: 100%; border-collapse: collapse; font-size: 15px; font-variant-numeric: tabular-nums; }
.ds-sheet th, .ds-sheet td { text-align: start; padding: 12px 14px; border-bottom: 1px solid var(--line, #e1e3ee); vertical-align: middle; }
.ds-sheet th { font-weight: 500; color: var(--muted, #454a63); font-size: 13px; white-space: nowrap; background: var(--raised, #f8f8fc); border-bottom-color: var(--line-strong, #c7cadb); }
.ds-sheet th:first-child, .ds-sheet td:first-child { padding-inline-start: 18px; }
.ds-sheet th:last-child, .ds-sheet td:last-child { padding-inline-end: 18px; }
.ds-sheet tbody tr:last-child td { border-bottom: 0; }
.ds-sheet tbody tr { transition: background-color 120ms ease-out; }
.ds-sheet tbody tr:hover td { background: var(--row, #f7f7fc); }
.ds-sheet a { color: var(--action-ink, #3f37a8); font-weight: 600; text-decoration: none; white-space: nowrap; }
.ds-sheet a:hover { text-decoration: underline; text-underline-offset: 3px; }
.ds-sheet a:focus-visible { outline: 2px solid var(--action, #4f46c8); outline-offset: 2px; }
.ds-sheet .ds-ok, .ds-sheet .ds-late, .ds-sheet .ds-wait { font-weight: 500; white-space: nowrap; }
.ds-sheet .ds-ok { color: var(--ontime, #0f7b5c); }
.ds-sheet .ds-late { color: var(--late, #b42318); }
.ds-sheet .ds-wait { color: var(--wait, #96590a); }
.ds-sheet .ds-ok::before, .ds-sheet .ds-late::before, .ds-sheet .ds-wait::before { content: ''; display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: currentColor; margin-inline-end: 8px; vertical-align: 0.1em; }
